package com.example.editor.remote.auth.provider;

import java.net.URI;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Component;
import com.example.editor.remote.auth.*;
import com.example.editor.remote.storage.RemoteStorageProperties;
import com.example.editor.remote.storage.RemoteStorageProviderType;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/** OAuth GitLab: usa Authorization Code + PKCE por defecto y conserva Device Authorization como opción administrada. */
@Component
public class GitLabOAuthProvider implements RemoteOAuthProvider {
    private final RemoteOAuthHttpClient http;private final ObjectMapper mapper;
    /** Descripción: Inicializa una instancia de GitLabOAuthProvider con sus dependencias y datos de entrada. Entradas: http: dato de entrada necesario para la operación; mapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ public GitLabOAuthProvider(RemoteOAuthHttpClient http,ObjectMapper mapper){this.http=http;this.mapper=mapper;}
    /** Descripción: Ejecuta la operación «type» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteStorageProviderType type(){return RemoteStorageProviderType.GITLAB;}
    /** Descripción: Ejecuta la operación «scopes» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public List<String> scopes(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth){return auth.getScopes().isEmpty()?List.of("api"):List.copyOf(auth.getScopes());}
    /** Descripción: Ejecuta la operación «useDeviceFlow» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación. Salida: devuelve un indicador que expresa el resultado de la condición. */ @Override public boolean useDeviceFlow(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth){requireClient(auth);return auth.isDeviceFlowPreferred();}
    /** Descripción: Ejecuta la operación «beginDeviceAuthorization» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteDeviceAuthorization beginDeviceAuthorization(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("scope",String.join(" ",scopes));
        RemoteOAuthHttpClient.Response response=http.postForm(URI.create(endpoint(storage,auth.getDeviceAuthorizationUrl(),"/oauth/authorize_device")),values,Map.of("Accept","application/json"));
        if(response.statusCode()==404)throw RemoteOAuthProviderErrorMapper.map(type(),"unsupported_grant_type","GitLab device authorization endpoint is not available");
        JsonNode json=RemoteOAuthProviderErrorMapper.requireSuccessJson(type(),mapper,response,"GitLab device authorization");
        String deviceCode=json.path("device_code").asText("");String userCode=json.path("user_code").asText("");String verification=json.path("verification_uri_complete").asText("");if(verification.isBlank())verification=json.path("verification_uri").asText("");long expires=Math.max(1L,json.path("expires_in").asLong(300L));int interval=Math.max(5,json.path("interval").asInt(5));
        if(deviceCode.isBlank()||userCode.isBlank()||verification.isBlank())throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,"GitLab device authorization returned an incomplete response");
        return new RemoteDeviceAuthorization(deviceCode,userCode,RemoteNetworkPolicy.requireHttps(URI.create(verification)),Instant.now().plusSeconds(expires),interval);
    }
    /** Descripción: Ejecuta la operación «pollDeviceAuthorization» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; deviceCode: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteDevicePollResult pollDeviceAuthorization(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String deviceCode,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("device_code",deviceCode);values.put("grant_type","urn:ietf:params:oauth:grant-type:device_code");
        RemoteOAuthHttpClient.Response response=http.postForm(URI.create(endpoint(storage,auth.getTokenUrl(),"/oauth/token")),values,Map.of("Accept","application/json"));JsonNode json=parseDeviceResponse(response);String error=json.path("error").asText("");
        if(response.successful()&&error.isBlank()){RemoteCredentialMaterial token=RemoteOAuthJsonSupport.token(type(),json,scopes,"","");return RemoteDevicePollResult.authorized(account(storage,auth,token));}
        int interval=Math.max(5,json.path("interval").asInt(5));
        return switch(error){case "authorization_pending"->RemoteDevicePollResult.pending(interval);case "slow_down"->RemoteDevicePollResult.slowDown(interval+5);case "access_denied","authorization_declined"->RemoteDevicePollResult.denied();case "expired_token"->RemoteDevicePollResult.expired();default->throw RemoteOAuthProviderErrorMapper.map(type(),error,json.path("error_description").asText(error));};
    }
    /** Descripción: Ejecuta la operación «authorizationUri» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; state: dato de entrada necesario para la operación; challenge: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public URI authorizationUri(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String state,String challenge,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("redirect_uri",redirect);values.put("response_type","code");values.put("scope",String.join(" ",scopes));values.put("state",state);values.put("code_challenge",challenge);values.put("code_challenge_method","S256");
        return URI.create(endpoint(storage,auth.getAuthorizationUrl(),"/oauth/authorize")+"?"+RemoteOAuthJsonSupport.query(values));
    }
    /** Descripción: Ejecuta la operación «exchange» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; code: dato de entrada necesario para la operación; verifier: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial exchange(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String code,String verifier,List<String> scopes){
        requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("code",code);values.put("grant_type","authorization_code");values.put("redirect_uri",redirect);values.put("code_verifier",verifier);if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());
        JsonNode json=RemoteOAuthProviderErrorMapper.requireSuccessJson(type(),mapper,http.postForm(URI.create(endpoint(storage,auth.getTokenUrl(),"/oauth/token")),values,Map.of("Accept","application/json")),"GitLab token exchange");
        return account(storage,auth,RemoteOAuthJsonSupport.token(type(),json,scopes,"",""));
    }
    /** Descripción: Ejecuta la operación «refresh» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial refresh(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){
        if(!current.refreshable())return current;requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("grant_type","refresh_token");values.put("refresh_token",current.refreshToken());if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());
        JsonNode json=RemoteOAuthProviderErrorMapper.requireSuccessJson(type(),mapper,http.postForm(URI.create(endpoint(storage,auth.getTokenUrl(),"/oauth/token")),values,Map.of("Accept","application/json")),"GitLab token refresh");
        RemoteCredentialMaterial token=RemoteOAuthJsonSupport.token(type(),json,current.scopes(),current.accountId(),current.accountLabel());
        if(token.refreshToken().isBlank())token=new RemoteCredentialMaterial(type(),token.accessToken(),current.refreshToken(),token.tokenType(),token.expiresAt(),token.scopes(),current.accountId(),current.accountLabel(),token.issuedAt());return token;
    }
    /** Descripción: Ejecuta la operación «revoke» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ @Override public void revoke(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){
        if(current==null||current.accessToken().isBlank())return;Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());values.put("token",current.accessToken());
        RemoteOAuthHttpClient.Response response=http.postForm(URI.create(endpoint(storage,auth.getRevokeUrl(),"/oauth/revoke")),values,Map.of());if(response.statusCode()!=200&&response.statusCode()!=204)throw new RemoteAuthException(RemoteAuthException.Reason.REMOTE_ERROR,"GitLab token revocation failed with HTTP "+response.statusCode()+": "+response.safeText());
    }
    /** Descripción: Ejecuta la operación «parseDeviceResponse» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: response: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private JsonNode parseDeviceResponse(RemoteOAuthHttpClient.Response response){try{return mapper.readTree(response.body());}catch(tools.jackson.core.JacksonException exception){throw new RemoteAuthException(RemoteAuthException.Reason.TOKEN_EXCHANGE_FAILED,"GitLab device authorization returned invalid JSON",exception);}}
    /** Descripción: Ejecuta la operación «account» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; token: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private RemoteCredentialMaterial account(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial token){
        String url=endpoint(storage,auth.getAccountUrl(),"/api/v4/user");JsonNode json=RemoteOAuthJsonSupport.parse(mapper,http.get(URI.create(url),Map.of("Authorization","Bearer "+token.accessToken())),"GitLab account lookup");return RemoteOAuthJsonSupport.withAccount(token,json.path("id").asText(""),json.path("username").asText("GitLab account"));
    }
    /** Descripción: Ejecuta la operación «endpoint» correspondiente a la responsabilidad de GitLabOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; configured: configuración que gobierna el comportamiento; suffix: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String endpoint(RemoteStorageProperties.Profile storage,String configured,String suffix){if(configured!=null&&!configured.isBlank()&&!configured.startsWith("https://gitlab.com"))return configured;String base=storage.getBaseUrl();if(base==null||base.isBlank())base="https://gitlab.com";base=base.replaceAll("/api/v4/?$","").replaceAll("/+$","");return base+suffix;}
    /** Descripción: Valida las condiciones necesarias para «requireClient» y rechaza entradas no válidas. Entradas: auth: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void requireClient(RemoteAuthProperties.Provider auth){if(auth==null||!auth.isEnabled()||auth.getClientId().isBlank())throw new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"GitLab OAuth requires a configured client ID");}
}
